from typing import List

def alive_count(deaths: List[int], t: int) -> int:
    return sum(1 for d in deaths if t < d)

def total_persistence(deaths: List[int], T: int) -> int:
    return sum(alive_count(deaths, t) for t in range(T))

def truncated_death_sum(deaths: List[int], T: int) -> int:
    return sum(min(d, T) for d in deaths)

def main() -> None:
    cases = [([1,2,4],7), ([1,2,4],3), ([3,3,5,8],6), ([1,1,1,1],10), ([],5)]
    for D, T in cases:
        lhs, rhs = total_persistence(D, T), truncated_death_sum(D, T)
        print(f'D={D!s:<14} T={T:<3} LHS={lhs:<3} RHS={rhs:<3} match={lhs==rhs}')

if __name__ == '__main__':
    main()

