function MIN_SPANNING_WEIGHT(edges, n):
    best <- infinity
    for each subset S of edges:
        if SPANS(S, n):              # reachability from 0 covers 0..n-1
            best <- min(best, sum of weights in S)
    return best                      # equals KRUSKAL_DEATHS sum

